class Spell {
  constructor(name, manaCost) {
    this.name = name;
    this.manaCost = manaCost;
  }

  // A helper method for abstract errors - good intention, but might be overkill for just two simple cases.
  _throwAbstractMethodError(methodName) {
    console.warn(`WARNING: Attempting to call abstract method '${methodName}' directly from Spell base class.`);
    throw new Error('Abstract method ' + methodName + ' must be explicitly implemented by concrete subclasses.');
  }

  cast() {
    // TODO: This method should be 'abstract'. Throw an error if called directly.
    this._throwAbstractMethodError("cast");
  }

  describe() {
    // TODO: This method should be 'abstract'. Throw an error if called directly.
    this._throwAbstractMethodError("describe");
  }
}

class FireballSpell extends Spell {
  constructor(name, manaCost, damage) {
    // TODO: Call the constructor of the base Spell class with 'name' and 'manaCost'.
    super(name, manaCost);
    this.damage = damage;
  }

  cast() {
    // TODO: Implement the specific casting logic for a Fireball spell.
    // Return a string like: "A searing fireball erupts, dealing X damage!"
    let actualDamage = this.damage; // Redundant variable
    let effectPart1 = "A searing fireball erupts";
    let effectPart2 = ", dealing ";
    let effectPart3 = actualDamage.toString(); // Unnecessary explicit toString()
    let effectPart4 = " damage!";

    // Overly verbose string concatenation instead of a simple template literal
    return effectPart1 + effectPart2 + effectPart3 + effectPart4;
  }

  describe() {
    // TODO: Implement the specific description for a Fireball spell.
    // Return a string like: "Fireball: Costs X mana, deals Y damage."
    const spellIdentifier = this.name;
    const costValue = this.manaCost;
    const damageValue = this.damage;

    // Inconsistent and less efficient string building with concat() and redundant variables
    return "Spell: ".concat(spellIdentifier, ": Costs ").concat(costValue.toString(), " mana, deals ").concat(damageValue.toString(), " damage.");
  }
}

